// Tally webhook payload structure:
// body.data.fields = array of { key, label, type, value }
const body = $input.first().json.body || $input.first().json;
const fields = body?.data?.fields || [];

// Helper: find field value by label (case-insensitive partial match)
function getField(labelSearch) {
  const match = fields.find(f =>
    f.label && f.label.toLowerCase().includes(labelSearch.toLowerCase())
  );
  if (!match) return null;

  // Handle dropdown/multiple choice — return human label not internal ID
  if (match.options && Array.isArray(match.options)) {
    const selected = match.options.find(o => o.id === match.value || o.value === match.value);
    if (selected) return selected.text || selected.label || selected.value;
  }

  if (Array.isArray(match.value)) return match.value.join(', ');
  return match.value || null;
}

// Extract fields from your Tally form
const name    = getField('name');
const email   = getField('email');
const phone   = getField('phone');
const role    = getField('I am a') || getField('role') || getField('am a');
const subject = getField('subject');
const message = getField('message') || getField('enquiry') || getField('question');

if (!message || message.trim().length === 0) {
  throw new Error('No enquiry message found in Tally submission');
}

// Build a clean enquiry string for Groq
let enquiryText = '';
if (name)    enquiryText += `From: ${name}`;
if (email)   enquiryText += ` <${email}>`;
if (phone)   enquiryText += ` | Phone: ${phone}`;
if (role)    enquiryText += ` | Role: ${role}`;
if (subject) enquiryText += `\nSubject: ${subject}`;
enquiryText += `\n\n${message}`;

return [{
  json: {
    enquiry_text:  enquiryText.trim(),
    sender_name:   name,
    sender_email:  email,
    sender_phone:  phone,
    sender_role:   role,
    subject:       subject,
    raw_message:   message,
    tally_form_id: body?.data?.formId || null,
    submission_id: body?.data?.submissionId || null,
    received_at:   new Date().toISOString()
  }
}];

const raw = $input.first().json.text;
const intake = $('Parse Tally Fields').first().json;

let classification;
try {
  classification = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse Groq response: ' + e.message);
}

const routingMap = {
  'Maintenance Request':  'James Okoye',
  'Levy / Fees':          'Priya Sharma',
  'OC Certificate':       'Sarah Mitchell',
  'AGM / Meetings':       'Sarah Mitchell',
  'Insurance':            'Linda Cross',
  'By-law / Compliance':  'Linda Cross',
  'New Client / Proposal':'Marcus Webb',
  'Building Access':      'Sarah Mitchell',
  'Legal Threat':         'Linda Cross',
  'General Enquiry':      'Sarah Mitchell'
};

const isLegalThreat = classification.is_legal_threat === true;
const isUrgentMaintenance = classification.is_urgent_maintenance === true;
const isHighPriority = classification.urgency === 'High' || isLegalThreat || isUrgentMaintenance;
const primaryRoute = routingMap[classification.enquiry_type] || 'Sarah Mitchell';

return [{
  json: {
    ...intake,
    classification,
    primary_route:        primaryRoute,
    is_high_priority:     isHighPriority,
    is_legal_threat:      isLegalThreat,
    is_urgent_maintenance: isUrgentMaintenance,
    processed_at:         new Date().toISOString()
  }
}];

const d = $input.first().json;
const c = d.classification;

const subject = `[${c.urgency}] ${c.enquiry_type} — ${d.sender_name || 'Unknown Sender'}`;

const htmlContent = `<h2 style="color:#1a1a2e">New Enquiry Assigned to You — ${c.assigned_to}</h2><table style="width:100%;font-family:sans-serif;font-size:14px;border-collapse:collapse"><tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold">From</td><td style="padding:8px;border:1px solid #ddd">${d.sender_name || 'Unknown'} &lt;${d.sender_email || '—'}&gt;</td></tr><tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold">Role</td><td style="padding:8px;border:1px solid #ddd">${d.sender_role || '—'}</td></tr><tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold">Phone</td><td style="padding:8px;border:1px solid #ddd">${d.sender_phone || '—'}</td></tr><tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold">Enquiry Type</td><td style="padding:8px;border:1px solid #ddd">${c.enquiry_type}</td></tr><tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold">Urgency</td><td style="padding:8px;border:1px solid #ddd">${c.urgency}</td></tr><tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold">Confidence</td><td style="padding:8px;border:1px solid #ddd">${Math.round(c.confidence * 100)}%</td></tr></table><h3>AI Summary</h3><p style="font-family:sans-serif;font-size:14px">${c.summary}</p><h3>Recommended Action</h3><p style="font-family:sans-serif;font-size:14px;background:#fff3cd;padding:12px;border-radius:4px">${c.recommended_action}</p><h3>Suggested Response</h3><blockquote style="border-left:4px solid #4a90e2;padding:12px;background:#f9f9f9;font-family:sans-serif;font-size:14px;font-style:italic">${c.suggested_response}</blockquote><hr><p style="font-family:sans-serif;font-size:12px;color:#999">Processed by Strata Enquiry AI · ${d.processed_at}</p>`;

const brevoPayload = JSON.stringify({
  sender: {
    name: "Strata Enquiry System",
    email: "YOUR_SENDER_EMAIL"
  },
  to: [
    {
      email: "YOUR_SENDER_EMAIL",
      name: "Test"
    }
  ],
  subject: subject,
  htmlContent: htmlContent
});

return [{
  json: {
    ...d,
    email_subject: subject,
    email_html: htmlContent,
    email_to: c.assigned_email,
    email_to_name: c.assigned_to,
    brevo_payload: brevoPayload
  }
}];
